style.css:
@-moz-document domain("open.spotify.com") {
html,
    body {
        background: url() center center / cover fixed no-repeat !important;
    }

    #root {
        background: transparent !important;
    }

    .Root,
    .Root__top-container,
    .Root__main-view,
    .main-view-container,
    [data-testid="main-view-container"] {
        background: transparent !important;
        background-color: transparent !important;
    }
}
